 157	
 158	    if (events & POLL_READABLE)
 159	        pevents |= UV_READABLE;
 160	    if (events & POLL_WRITABLE)
 161	        pevents |= UV_WRITABLE;
 162	    if (events & POLL_DISCONNECT)
