 171	    int revents = 0;
 172	
 173	    if (poll->callback) {
 174	        if (status != 0)
 175	            revents |= POLL_ERROR;
 176	        if (events & UV_READABLE)
 177	            revents |= POLL_READABLE;
 178	        if (events & UV_WRITABLE)
