   229	int service_loop_run(bool start_thread, char* name)
   230	{
   231	    uv_loop_t* handle = get_service_uv_loop();
   232	    service_loop_t* loop = handle->data;
   233	
   234	    if (start_thread) {
   235	        int ret = uv_sem_init(&loop->ready, 0);
   236	        if (ret != 0) {
   237	            BT_LOGE("%s sem init error: %d", __func__, ret);
   238	            return ret;
   239	        }
   240	
   241	        uv_thread_options_t options = {
   242	            UV_THREAD_HAS_STACK_SIZE | UV_THREAD_HAS_PRIORITY,
   243	            CONFIG_BLUETOOTH_SERVICE_LOOP_THREAD_STACK_SIZE,
   244	            CONFIG_BLUETOOTH_SERVICE_LOOP_THREAD_PRIORITY
   245	        };
   246	        ret = uv_thread_create_ex(&loop->thread, &options, service_schedule_loop, loop);
   247	        if (ret != 0) {
   248	            BT_LOGE("service loop thread create :%d", ret);
   249	            return ret;
   250	        }
   251	
   252	        if (name != NULL && strlen(name) > 0)
   253	            snprintf(loop->name, sizeof(loop->name), "%s_%d", name, getpid());
   254	        else
   255	            snprintf(loop->name, sizeof(loop->name), "loop_%d", getpid());
   256	        pthread_setname_np(loop->thread, loop->name);
   257	        uv_sem_wait(&loop->ready);
   258	        uv_sem_destroy(&loop->ready);
   259	        BT_LOGD("%s loop running now !!!", loop->name);
   260	    } else {
   261	        pthread_setschedprio(loop->thread, CONFIG_BLUETOOTH_SERVICE_LOOP_THREAD_PRIORITY);
   262	
   263	        BT_LOGD("service loop running now !!!");
   264	        service_schedule_loop(loop);
   265	    }
   266	
   267	    return 0;
   268	}
