   311	    }
   312	
   313	    list_delete(&loop->msg_queue);
   314	    list_delete(&loop->deferred_queue);
   315	    uv_mutex_unlock(&loop->msg_lock);
   316	    uv_mutex_destroy(&loop->msg_lock);
   317	    free(loop);
